css:
@page { size: A4; margin: 12mm; }
body { font-family: 'DejaVu Sans', sans-serif; color: #1f2937; font-size: 10pt; }
.kashf-header { border-bottom: 3px solid #0f766e; padding-bottom: 12px; margin-bottom: 16px; }
.kashf-header h1 { color: #0f766e; margin: 0 0 5px; }
.kashf-header img { float: right; max-height: 58px; max-width: 150px; }
.meta, .items { width: 100%; border-collapse: collapse; margin: 12px 0; }
.meta td { width: 25%; padding: 7px; border: 1px solid #d1d5db; vertical-align: top; }
.label { color: #6b7280; display: block; font-size: 8pt; text-transform: uppercase; }
.items th { background: #0f766e; color: white; padding: 7px; text-align: left; }
.items td { padding: 7px; border: 1px solid #d1d5db; }
.result { border: 2px solid #0f766e; padding: 10px; margin-top: 16px; font-size: 12pt; }
.notes { white-space: pre-wrap; }

html:
{% set company = frappe.get_doc('Company', doc.company) if doc.company else none %}
{% set profile_name = frappe.db.get_value('Captain Profile', {'user': doc.captain_user}, 'full_name') or doc.driver_name_text or doc.captain_user %}
{% set vehicle = frappe.get_doc('Vehicle', doc.vehicle) if doc.vehicle else none %}
{% set trip = frappe.get_doc('Trip', doc.trip) if doc.trip else none %}
{% set route = frappe.get_doc('Route', doc.route) if doc.route else none %}
<div class="kashf-header">
  {% if company and company.logo %}<img src="{{ company.logo | abs_url }}">{% endif %}
  <h1>Vehicle Kashf / Inspection</h1>
  <div>{{ company.company_name if company else '' }}</div>
  <div>{{ doc.inspection_no or doc.name }}</div>
</div>
<table class="meta">
  <tr><td><span class="label">Driver</span>{{ profile_name }}</td><td><span class="label">Date</span>{{ frappe.utils.formatdate(doc.inspection_date) }}</td><td><span class="label">Trip</span>{{ (trip.trip_code or trip.name) if trip else '-' }}</td><td><span class="label">Trip status</span>{{ trip.trip_status if trip else '-' }}</td></tr>
  <tr><td><span class="label">Route</span>{{ (route.route_title or route.name) if route else '-' }}</td><td><span class="label">From / To</span>{{ ((route.source or '') ~ ' - ' ~ (route.destination or '')) if route else '-' }}</td><td><span class="label">Vehicle</span>{{ vehicle.vehicle_name if vehicle else doc.vehicle }}</td><td><span class="label">Plate</span>{{ vehicle.plate_no if vehicle else '-' }}</td></tr>
  <tr><td><span class="label">Current city</span>{{ doc.current_city or '-' }}</td><td><span class="label">Target city</span>{{ doc.target_city or '-' }}</td><td><span class="label">Location</span>{{ doc.latitude or '' }}, {{ doc.longitude or '' }}</td><td><span class="label">Odometer</span>{{ doc.odometer or '-' }} km</td></tr>
</table>
{% if doc.detected_address %}<p><strong>Detected address:</strong> {{ doc.detected_address }}</p>{% endif %}
<table class="items"><thead><tr><th>#</th><th>Category</th><th>Inspection item</th><th>Result</th><th>Notes</th></tr></thead><tbody>
{% for row in doc.items %}<tr><td>{{ loop.index }}</td><td>{{ row.category or row.section or '' }}</td><td>{{ row.item or row.item_en or '' }}</td><td>{{ row.status or '' }}</td><td>{{ row.notes or '' }}</td></tr>{% endfor %}
</tbody></table>
<div class="result"><strong>Overall result:</strong> {{ doc.overall_result or 'Pending' }} &nbsp; <strong>Status:</strong> {{ doc.status or 'Draft' }}</div>
{% if doc.overall_notes %}<p class="notes"><strong>Overall notes:</strong><br>{{ doc.overall_notes }}</p>{% endif %}
